'use client';

/**
 * Spectrum UI: Pricing tiers
 *
 * Four three-tier pricing layouts from the Spectrum UI pricing collection
 * behind one `variant` prop: a banner grid with a yearly/monthly switch and
 * rolling price digits, tinted gradient columns, staggered offset cards and a
 * set of printed receipts. Each layout is also exported on its own and takes
 * the same `Plan[]` shape.
 */

import { BannerTiers, type BannerTiersProps } from './pricing-tiers-banner';
import { GradientTiers, type GradientTiersProps } from './pricing-tiers-gradient';
import { OffsetTiers, type OffsetTiersProps } from './pricing-tiers-offset';
import { ReceiptTiers, type ReceiptTiersProps } from './pricing-tiers-receipt';
import type { Plan } from './pricing-tiers-types';

export { BannerTiers, GradientTiers, OffsetTiers, ReceiptTiers };
export type { BannerTiersProps, GradientTiersProps, OffsetTiersProps, ReceiptTiersProps };
export { PriceFigure } from './pricing-tiers-price-figure';
export type * from './pricing-tiers-types';

export type PricingTiersVariant = 'banner' | 'gradient' | 'offset' | 'receipt';

export const DEFAULT_PLANS: Plan[] = [
  {
    id: 'starter',
    name: 'Starter',
    tagline: 'For solo builders shipping their first product.',
    price: { monthly: 12, annual: 9 },
    cta: 'Start free trial',
    features: ['3 projects', '10k monthly events', 'Email support', 'Community templates'],
  },
  {
    id: 'growth',
    name: 'Growth',
    tagline: 'For teams that need more seats, more data and fewer limits.',
    price: { monthly: 49, annual: 39 },
    cta: 'Upgrade to Growth',
    featured: true,
    badge: 'Popular',
    inherits: 'Starter',
    features: ['Unlimited projects', '1M monthly events', 'Priority support', 'Audit log'],
  },
  {
    id: 'enterprise',
    name: 'Enterprise',
    tagline: 'For organisations with security and procurement needs.',
    price: null,
    cta: 'Talk to sales',
    inherits: 'Growth',
    features: ['SAML SSO & SCIM', 'Custom data retention', 'Dedicated manager', '99.99% uptime SLA'],
  },
];

export interface PricingTiersProps {
  variant?: PricingTiersVariant;
  plans?: Plan[];
  heading?: string;
  subheading?: string;
  eyebrow?: string;
  className?: string;
}

export function PricingTiers({
  variant = 'banner',
  plans = DEFAULT_PLANS,
  eyebrow = 'Pricing',
  heading = 'Simple plans that grow with your team',
  subheading = 'Start free for 14 days. No card required, cancel any time.',
  className,
}: PricingTiersProps) {
  if (variant === 'gradient') {
    return (
      <GradientTiers
        plans={plans}
        eyebrow={eyebrow}
        heading={heading}
        subheading={subheading}
        notes={plans.map((plan) => ({
          price: plan.price ? `$${plan.price.annual} / mo` : undefined,
          priceNote: plan.price ? 'per seat, billed yearly' : 'Volume discounts',
        }))}
        className={className}
      />
    );
  }

  if (variant === 'offset') {
    return (
      <OffsetTiers
        plans={plans}
        eyebrow={eyebrow}
        heading={heading}
        subheading={subheading}
        className={className}
      />
    );
  }

  if (variant === 'receipt') {
    return (
      <ReceiptTiers
        plans={plans}
        eyebrow={eyebrow}
        heading={heading}
        subheading={subheading}
        merchant="NORTHWIND LABS INC."
        merchantLine="548 MARKET ST · SAN FRANCISCO"
        className={className}
      />
    );
  }

  return <BannerTiers plans={plans} eyebrow={eyebrow} heading={heading} className={className} />;
}

export default PricingTiers;

'use client';

import { useState } from 'react';
import { Check } from 'lucide-react';
import { cn } from '@/lib/utils';
import { PriceFigure } from './pricing-tiers-price-figure';
import { REVEAL_KEYFRAMES, revealClass, revealDelay, useReveal } from './pricing-tiers-reveal';
import type { Plan } from './pricing-tiers-types';

export type BannerTiersVariant = 'Banner' | 'Badge';

export interface BannerTiersProps {
  plans: Plan[];
  eyebrow?: string;
  heading: string;
  variant?: BannerTiersVariant;
  className?: string;
}

export function BannerTiers({
  plans,
  eyebrow = 'Pricing',
  heading,
  variant = 'Banner',
  className,
}: BannerTiersProps) {
  const [yearly, setYearly] = useState(true);
  const { ref, shown } = useReveal<HTMLElement>();
  const banner = variant === 'Banner';
  const featuredIndex = Math.max(
    0,
    plans.findIndex((plan) => plan.featured),
  );

  return (
    <section
      ref={ref}
      className={cn(
        '@container w-full bg-white px-6 pb-10 pt-12 dark:bg-[#0c0c0e] sm:px-10',
        className,
      )}
    >
      <style dangerouslySetInnerHTML={{ __html: REVEAL_KEYFRAMES }} />

      <div className={cn('flex flex-col items-center text-center', revealClass(shown))}>
        <span className="flex items-center gap-2.5 border border-[#d4d4d8] px-3.5 py-2 dark:border-[#33333a]">
          <span aria-hidden className="size-2 bg-[#2337f0]" />
          <span className="font-mono text-[12px] font-medium uppercase tracking-[0.1em] text-[#18181b] dark:text-[#f4f4f5]">
            {eyebrow}
          </span>
        </span>
        <h2 className="mt-7 max-w-[24ch] text-balance [font-family:var(--font-spectral,Georgia,serif)] text-[26px] font-normal leading-[1.08] tracking-[-0.6px] text-[#0a0a0a] dark:text-white @sm:text-[34px] @lg:text-[44px]">
          {heading}
        </h2>

        <div className="mt-8 flex items-center gap-3">
          <span
            className={cn(
              'text-[15px]',
              yearly ? 'text-[#0a0a0a] dark:text-white' : 'text-[#71717a] dark:text-[#8f8f96]',
            )}
          >
            Yearly
          </span>
          <button
            type="button"
            role="switch"
            aria-checked={!yearly}
            aria-label="Bill monthly"
            onClick={() => setYearly((value) => !value)}
            className={cn(
              'relative h-7 w-[74px] border border-[#c9c9cf] bg-white dark:border-[#3f3f46] dark:bg-[#1a1a1e]',
              'focus-visible:outline-hidden focus-visible:ring-2 focus-visible:ring-[#2337f0] focus-visible:ring-offset-2',
            )}
          >
            <span
              aria-hidden
              className={cn(
                'absolute top-0.5 left-0.5 h-[22px] w-[33px] bg-[#2337f0]',
                'transition-transform duration-200 ease-[cubic-bezier(0.23,1,0.32,1)] motion-reduce:transition-none',
                !yearly && 'translate-x-[35px]',
              )}
            />
          </button>
          <span
            className={cn(
              'text-[15px]',
              !yearly ? 'text-[#0a0a0a] dark:text-white' : 'text-[#71717a] dark:text-[#8f8f96]',
            )}
          >
            Monthly
          </span>
        </div>
      </div>

      <div className={cn('grid @3xl:grid-cols-3', banner ? 'mt-24' : 'mt-12')}>
        {plans.map((plan, position) => {
          const featured = plan.featured;
          const amount = plan.price ? (yearly ? plan.price.annual : plan.price.monthly) : null;

          return (
            <div
              key={plan.id}
              style={revealDelay(shown, position)}
              className={cn(
                'relative flex flex-col border border-[#e4e4e7] dark:border-[#2b2b31]',
                revealClass(shown),
                'mt-14 first:mt-0 @3xl:mt-0',
                position < featuredIndex && '@3xl:border-r-0',
                position > featuredIndex && '@3xl:border-l-0',
                featured && 'z-10 border-[#2337f0] dark:border-[#4356ff]',
              )}
            >
              {featured && banner && (
                <div className="absolute inset-x-[-1px] -top-12 flex h-12 items-center justify-center bg-[#2337f0] text-[19px] font-medium text-white dark:bg-[#4356ff]">
                  Most popular
                </div>
              )}

              <div className="px-8 pb-8 pt-8">
                <div className="flex items-center justify-between gap-3">
                  <h3 className="text-[21px] font-semibold tracking-[-0.3px] text-[#0a0a0a] dark:text-white">
                    {plan.name}
                  </h3>
                  {featured && !banner && (
                    <span className="bg-[#2337f0] px-2.5 py-1 font-mono text-[10.5px] font-medium uppercase tracking-[0.08em] text-white">
                      Most popular
                    </span>
                  )}
                </div>
                <p className="mt-2.5 min-h-[44px] text-pretty text-[14.5px] leading-[1.5] text-[#52525b] dark:text-[#a1a1a8]">
                  {plan.tagline}
                </p>

                <div className="mt-5 flex items-end gap-1.5">
                  {amount === null ? (
                    <span className="text-[34px] font-semibold leading-none tracking-[-2px] text-[#0a0a0a] dark:text-white @sm:text-[42px] @lg:text-[48px]">
                      Custom
                    </span>
                  ) : (
                    <>
                      <PriceFigure
                        value={amount}
                        className="text-[34px] font-semibold tracking-[-2px] text-[#0a0a0a] dark:text-white @sm:text-[42px] @lg:text-[48px]"
                      />
                      <span className="pb-1.5 text-[15px] text-[#71717a] dark:text-[#8f8f96]">
                        / mo
                      </span>
                    </>
                  )}
                </div>

                <button
                  type="button"
                  className={cn(
                    'mt-6 h-[50px] w-full font-mono text-[14.5px]',
                    'transition-[transform,background-color] duration-150 active:scale-[0.98]',
                    'focus-visible:outline-hidden focus-visible:ring-2 focus-visible:ring-[#2337f0] focus-visible:ring-offset-2',
                    featured
                      ? 'bg-[#2337f0] text-white hover:bg-[#1b2cd1]'
                      : 'bg-[#0a0a0a] text-white hover:bg-black dark:bg-[#f4f4f5] dark:text-[#0c0c0e] dark:hover:bg-white',
                  )}
                >
                  {plan.cta}
                </button>
              </div>

              <ul className="flex-1">
                {plan.features.map((feature) => (
                  <li
                    key={feature}
                    className="flex items-center gap-3.5 border-t border-[#e4e4e7] px-8 py-[19px] dark:border-[#2b2b31]"
                  >
                    <span
                      aria-hidden
                      className="grid size-[22px] shrink-0 place-items-center rounded-full border border-[#aeb6f8] dark:border-[#3c4494]"
                    >
                      <Check
                        className="size-3 text-[#2337f0] dark:text-[#93a0ff]"
                        strokeWidth={2.4}
                      />
                    </span>
                    <span className="text-[15px] text-[#27272a] dark:text-[#d4d4da]">
                      {feature}
                    </span>
                  </li>
                ))}
              </ul>
            </div>
          );
        })}
      </div>
    </section>
  );
}

export default BannerTiers;

'use client';

import { ArrowRight, Building2, FileText, TrendingUp } from 'lucide-react';
import { cn } from '@/lib/utils';
import { REVEAL_KEYFRAMES, revealClass, revealDelay, useReveal } from './pricing-tiers-reveal';
import type { Plan } from './pricing-tiers-types';

export type GradientTiersVariant = 'Tinted' | 'Plain';

export interface GradientTierNote {
  price?: string;
  priceNote?: string;
  footnote?: string;
}

export interface GradientTiersProps {
  plans: Plan[];
  eyebrow?: string;
  heading?: string;
  subheading?: string;
  notes?: GradientTierNote[];
  variant?: GradientTiersVariant;
  className?: string;
}

const PALETTE = [
  {
    icon: FileText,
    wash: 'from-[#e8efff] dark:from-[#1a2338]',
    iconColor: 'text-[#4a7dfc] dark:text-[#8fadff]',
    label: 'text-[#8a8580] dark:text-[#98938d]',
  },
  {
    icon: TrendingUp,
    wash: 'from-[#f3f7d4] dark:from-[#272b10]',
    iconColor: 'text-[#7f931c] dark:text-[#bdd14b]',
    label: 'text-[#7f931c] dark:text-[#bdd14b]',
  },
  {
    icon: Building2,
    wash: 'from-[#f5ecfe] dark:from-[#2a1c3c]',
    iconColor: 'text-[#a34df0] dark:text-[#c894f7]',
    label: 'text-[#4a7dfc] dark:text-[#8fadff]',
  },
];

export function GradientTiers({
  plans,
  eyebrow,
  heading,
  subheading,
  notes = [],
  variant = 'Tinted',
  className,
}: GradientTiersProps) {
  const { ref, shown } = useReveal<HTMLElement>();

  return (
    <section ref={ref} className={cn('@container w-full', className)}>
      <style dangerouslySetInnerHTML={{ __html: REVEAL_KEYFRAMES }} />

      {heading && (
        <div className={cn('mx-auto mb-10 max-w-[54ch] text-center', revealClass(shown))}>
          {eyebrow && (
            <span className="inline-flex items-center gap-2.5">
              <span aria-hidden className="flex gap-1">
                <span className="size-1.5 rounded-full bg-[#4a7dfc]" />
                <span className="size-1.5 rounded-full bg-[#7f931c]" />
                <span className="size-1.5 rounded-full bg-[#a34df0]" />
              </span>
              <span className="text-[12px] font-semibold uppercase tracking-[0.12em] text-[#78716c] dark:text-[#98938d]">
                {eyebrow}
              </span>
            </span>
          )}
          <h2 className="mt-4 text-balance [font-family:var(--font-spectral,Georgia,serif)] text-[28px] font-normal leading-[1.08] tracking-[-0.5px] text-[#1c1b1a] dark:text-[#f5f5f4] @sm:text-[34px] @lg:text-[42px]">
            {heading}
          </h2>
          {subheading && (
            <p className="mt-3 text-pretty text-[16px] leading-[1.55] text-[#57534e] dark:text-[#a8a29e]">
              {subheading}
            </p>
          )}
        </div>
      )}

      <div className="grid w-full grid-cols-1 overflow-hidden border border-[#e2e0dd] bg-white @3xl:grid-cols-3 dark:border-[#2b2b30] dark:bg-[#0f0f11]">
        {plans.map((plan, position) => {
          const palette = PALETTE[position % PALETTE.length];
          const Icon = palette.icon;
          const note = notes[position] ?? {};

          return (
            <div
              key={plan.id}
              style={revealDelay(shown, position)}
              className={cn(
                'relative flex flex-col border-t border-[#e2e0dd] px-8 pb-10 pt-9 first:border-t-0 @3xl:border-l @3xl:border-t-0 @3xl:first:border-l-0 dark:border-[#2b2b30]',
                revealClass(shown),
              )}
            >
              {variant === 'Tinted' && (
                <span
                  aria-hidden
                  className={cn(
                    'absolute inset-x-0 top-0 h-[46%] bg-gradient-to-b to-transparent',
                    palette.wash,
                  )}
                />
              )}

              <div className="relative">
                <div className="flex items-start justify-between">
                  <Icon aria-hidden className={cn('size-6', palette.iconColor)} strokeWidth={1.8} />
                  {plan.badge && (
                    <span className="rounded-full bg-[#e7edc4] px-3.5 py-1.5 text-[14px] font-medium text-[#5b661c] dark:bg-[#2e3413] dark:text-[#cade5e]">
                      {plan.badge}
                    </span>
                  )}
                </div>

                <h3 className="mt-6 [font-family:var(--font-spectral,Georgia,serif)] text-[30px] font-normal leading-none tracking-[-0.5px] text-[#1c1b1a] dark:text-[#f5f5f4] @sm:text-[34px] @lg:text-[38px]">
                  {plan.name}
                </h3>
                <p className="mt-3 text-pretty text-[16.5px] leading-[1.5] text-[#57534e] dark:text-[#a8a29e]">
                  {plan.tagline}
                </p>

                <div className="mt-7 flex min-h-[42px] items-baseline justify-between gap-4">
                  <span className="whitespace-nowrap text-[27px] font-semibold tracking-[-0.5px] text-[#1c1b1a] dark:text-[#f5f5f4]">
                    {note.price ?? 'Custom pricing'}
                  </span>
                  {note.priceNote && (
                    <span className="text-right text-[15px] leading-snug text-[#78716c] dark:text-[#8f8a85]">
                      {note.priceNote}
                    </span>
                  )}
                </div>

                <button
                  type="button"
                  className={cn(
                    'group mt-6 flex h-[52px] w-full items-center justify-center gap-2 rounded-[3px] text-[16px] font-medium',
                    'transition-[transform,background-color,border-color] duration-150 active:scale-[0.98]',
                    'focus-visible:outline-hidden focus-visible:ring-2 focus-visible:ring-[#4a7dfc] focus-visible:ring-offset-2',
                    position === 0
                      ? 'border border-black/40 bg-[#3a3733] text-white shadow-[inset_0_0_0_1px_rgba(255,255,255,0.14)] hover:bg-[#292624] dark:border-white/20 dark:bg-[#f5f5f4] dark:text-[#1c1917] dark:shadow-[inset_0_0_0_1px_rgba(0,0,0,0.08)] dark:hover:bg-white'
                      : 'border border-[#d9d6d2] bg-white text-[#453f54] hover:border-[#b9b5af] dark:border-white/[0.15] dark:bg-transparent dark:text-[#d3cde2] dark:hover:border-white/[0.3]',
                  )}
                >
                  {plan.cta}
                  {position > 0 && (
                    <ArrowRight
                      aria-hidden
                      className="size-4 transition-transform duration-[180ms] ease-[cubic-bezier(0.23,1,0.32,1)] group-hover:translate-x-0.5 motion-reduce:transition-none"
                    />
                  )}
                </button>

                <p
                  className={cn(
                    'mt-9 text-[13px] font-semibold uppercase tracking-[0.05em]',
                    palette.label,
                  )}
                >
                  {plan.inherits ? `Everything in ${plan.inherits}, plus:` : 'Core functionality'}
                </p>

                <ul className="mt-6 space-y-[18px]">
                  {plan.features.map((feature) => (
                    <li key={feature} className="flex items-baseline gap-3.5">
                      <svg
                        viewBox="0 0 16 16"
                        fill="none"
                        aria-hidden
                        className="size-4 shrink-0 translate-y-0.5 text-[#1c1b1a] dark:text-[#f5f5f4]"
                      >
                        <path
                          d="m2.5 9 3.5 3.5L13.5 4"
                          stroke="currentColor"
                          strokeWidth="1.6"
                          strokeLinecap="round"
                          strokeLinejoin="round"
                        />
                      </svg>
                      <span className="text-[16.5px] leading-[1.45] text-[#292524] dark:text-[#d6d3d1]">
                        {feature}
                      </span>
                    </li>
                  ))}
                </ul>

                {note.footnote && (
                  <p className="mt-10 text-center text-[15.5px] text-[#57534e] dark:text-[#a8a29e]">
                    {note.footnote}
                  </p>
                )}
              </div>
            </div>
          );
        })}
      </div>
    </section>
  );
}

export default GradientTiers;

'use client';

import { ArrowRight, Check } from 'lucide-react';
import { cn } from '@/lib/utils';
import { REVEAL_KEYFRAMES, revealClass, revealDelay, useReveal } from './pricing-tiers-reveal';
import type { Plan } from './pricing-tiers-types';

export type OffsetTiersVariant = 'Staggered' | 'Level';

export interface OffsetTiersProps {
  plans: Plan[];
  eyebrow?: string;
  heading?: string;
  subheading?: string;
  currency?: string;
  variant?: OffsetTiersVariant;
  className?: string;
}

const OFFSETS = ['@3xl:mt-0', '@3xl:mt-10', '@3xl:mt-20'];

export function OffsetTiers({
  plans,
  eyebrow,
  heading,
  subheading,
  currency = '$',
  variant = 'Staggered',
  className,
}: OffsetTiersProps) {
  const { ref, shown } = useReveal<HTMLElement>();
  const staggered = variant === 'Staggered';

  return (
    <section
      ref={ref}
      className={cn(
        '@container relative w-full bg-white px-6 py-10 sm:px-10 sm:py-14 dark:bg-[#0b0b0d]',
        '[background-image:radial-gradient(circle,#d9d9d9_1px,transparent_1px)] [background-size:13px_13px]',
        'dark:[background-image:radial-gradient(circle,#2a2a2e_1px,transparent_1px)]',
        className,
      )}
    >
      <style dangerouslySetInnerHTML={{ __html: REVEAL_KEYFRAMES }} />

      {heading && (
        <div className={cn('mb-12 max-w-[52ch]', revealClass(shown))}>
          {eyebrow && (
            <span className="flex items-center gap-2.5">
              <span aria-hidden className="size-2 rounded-full bg-[#6f88f7]" />
              <span className="text-[12px] font-medium uppercase tracking-[0.14em] text-[#6b6b70] dark:text-[#9d9da5]">
                {eyebrow}
              </span>
            </span>
          )}
          <h2 className="mt-4 text-balance [font-family:var(--font-spectral,Georgia,serif)] text-[28px] font-normal leading-[1.05] tracking-[-0.5px] text-[#111113] @sm:text-[34px] @lg:text-[40px] dark:text-[#f4f4f5]">
            {heading}
          </h2>
          {subheading && (
            <p className="mt-4 text-pretty text-[16px] leading-[1.55] text-[#6b6b70] dark:text-[#9d9da5]">
              {subheading}
            </p>
          )}
        </div>
      )}

      <div className="grid grid-cols-1 gap-8 @3xl:grid-cols-3 @3xl:gap-9">
        {plans.map((plan, position) => (
          <div
            key={plan.id}
            style={revealDelay(shown, position)}
            className={cn(
              'flex flex-col border border-[#e4e4e4] bg-white transition-[border-color,box-shadow] duration-200 dark:border-[#28282d] dark:bg-[#111113]',
              '[@media(hover:hover)]:hover:border-[#c9c9cc] [@media(hover:hover)]:hover:shadow-[0_16px_40px_-28px_rgba(0,0,0,0.25)] dark:[@media(hover:hover)]:hover:border-[#3a3a41]',
              revealClass(shown),
              staggered && OFFSETS[position % OFFSETS.length],
            )}
          >
            <div className="px-5 pb-9 pt-10 @sm:px-8 @lg:px-9">
              <h3 className="[font-family:var(--font-spectral,Georgia,serif)] text-[30px] font-normal leading-none tracking-[-0.5px] text-[#111113] @sm:text-[36px] @lg:text-[40px] dark:text-[#f4f4f5]">
                {plan.name}
              </h3>
              <p className="mt-5 text-pretty text-[16px] leading-[1.55] text-[#6b6b70] dark:text-[#9d9da5]">
                {plan.tagline}
              </p>
            </div>

            <div className="flex-1 border-t border-[#e4e4e4] dark:border-[#28282d] px-5 py-9 @sm:px-8 @lg:px-9">
              {plan.inherits && (
                <p className="mb-7 text-[16.5px] font-medium leading-snug text-[#26262a] dark:text-[#e7e7ec]">
                  Includes everything in {plan.inherits}, plus:
                </p>
              )}
              <ul className="space-y-5">
                {plan.features.map((feature) => (
                  <li key={feature} className="flex gap-3.5">
                    <span
                      aria-hidden
                      className="mt-0.5 grid size-[21px] shrink-0 place-items-center rounded-full bg-[#6f88f7]"
                    >
                      <Check className="size-3 text-white" strokeWidth={3} />
                    </span>
                    <span className="text-[15.5px] leading-[1.5] text-[#3d3d42] dark:text-[#c6c6cd]">
                      {feature}
                    </span>
                  </li>
                ))}
              </ul>
            </div>

